// App 'Inovação sem Fronteiras' — servido embutido (base64) para funcionar
// tanto via GET quanto via POST (o Bitrix, no modo Servidor, envia por POST).

const HTML_B64 = "";

export default function handler(req, res) {
  if (req.method === 'OPTIONS') { res.status(204).end(); return; }
  if (req.method !== 'GET' && req.method !== 'POST') { res.status(405).end(); return; }
  res.setHeader('Content-Type', 'text/html; charset=utf-8');
  res.removeHeader('X-Frame-Options');
  res.status(200).send(Buffer.from(HTML_B64, 'base64').toString('utf8'));
}
